from datetime import datetime, timedelta
from apscheduler.schedulers.blocking import BlockingScheduler  # type: ignore
from apscheduler.schedulers.background import BackgroundScheduler  # type: ignore
from taf.ul.sc import perf
from taf.ul.sc.perf.util.logger import log_info_to_console
from taf.ul.sc.perf.util.helpers import round_time_to_seconds


class TestDurationManager(object):
    __test__ = False
    _instance = None
    _max_recovery_time = 60 * 60

    def __new__(cls, *args, **kwargs):
        if not isinstance(cls._instance, TestDurationManager):
            cls._instance = object.__new__(TestDurationManager)
            cls._instance.__initialized = False
        return cls._instance

    def __init__(self):
        if self.__initialized:
            return

        self._sleep_job = None
        self._cancel_job = None
        self._bgscheduler = BackgroundScheduler()
        self._fgsheduler = BlockingScheduler()
        self._execution_start = None
        self._execution_end = None
        self.__initialized = True

    @property
    def max_recovery_time(self):
        return TestDurationManager._max_recovery_time

    @property
    def execution_start(self):
        return self._execution_start

    def set_execution_start(self):
        self._execution_start = datetime.now()

    def calculate_execution_end(self, seconds):
        self._execution_end = self._execution_start + timedelta(seconds=seconds)

    @property
    def execution_end(self):
        return self._execution_end

    def sleep(self, seconds, interval=None):
        if not self.execution_start:
            self.set_execution_start()
        self.calculate_execution_end(seconds)
        if interval is None:
            interval = self._get_interval(duration=seconds)
        self._start_cancel_job(run_date=self._execution_end + timedelta(milliseconds=250))
        self._start_sleep_job(interval)

        return self.execution_end

    @staticmethod
    def _get_interval(duration):
        if duration <= 20 * 60:
            interval = 60
        elif 20 * 60 < duration <= 2 * 60 * 60:
            interval = 10 * 60
        else:
            interval = 60 * 60

        return interval

    def _start_cancel_job(self, run_date):
        self._cancel_job = self._bgscheduler.add_job(func=self._cancel_sleep, trigger='date', run_date=run_date)
        if self._bgscheduler.state == 0:
            self._bgscheduler.start()

    def _start_sleep_job(self, interval):
        self._sleep_job = self._fgsheduler.add_job(func=self._heartbeat, trigger='interval', seconds=interval,
                                                   next_run_time=self._get_time_of_first_heartbeat(interval))
        if self._fgsheduler.state == 0:
            self._fgsheduler.start()

    def _get_time_of_first_heartbeat(self, interval):
        first_heartbeat = self.execution_start + timedelta(seconds=interval)
        return first_heartbeat

    def _heartbeat(self):
        elapsed = datetime.now() - self._execution_start
        remain = self._execution_end - datetime.now()
        duration = self._execution_end - self._execution_start
        progress = elapsed.total_seconds() / duration.total_seconds()
        progress_int = "{:.0%}".format(progress)
        msg = "Progress: {:<4} Elapsed: {:>8} Remained: {:>8}".format(progress_int,
                                                                      str(round_time_to_seconds(elapsed)),
                                                                      str(round_time_to_seconds(remain)))
        log_info_to_console(msg=msg, log_hierarchy=2)
        if not perf.tl.ue.is_scenario_running():
            log_info_to_console("Scenario not running anymore. Exiting sleep.", log_hierarchy=2)
            self.break_test()

        return msg

    def _cancel_sleep(self):
        self._fgsheduler.shutdown(wait=False)
        self._fgsheduler = BlockingScheduler()

    def modify_test_duration(self, run_date):
        self._execution_end = run_date
        self._bgscheduler.reschedule_job(job_id=self._cancel_job.id, trigger='date', run_date=run_date)
        return run_date

    def extend_test_duration(self, seconds):
        run_date = self._execution_end + timedelta(seconds=seconds)
        return self.modify_test_duration(run_date)

    def reduce_test_duration(self, seconds):
        run_date = self._execution_end - timedelta(seconds=seconds)
        return self.modify_test_duration(run_date)

    def break_test(self, offset=30):
        run_date = datetime.now() + timedelta(seconds=offset)
        return self.modify_test_duration(run_date)

    def how_many_to_end_of_execution(self):
        """
        Returns how many seconds left to the end of test scenario
        :return:
        """
        time_to_end = self._execution_end - datetime.now()
        return time_to_end.total_seconds()

    def is_time_enough_to_perform_recovery(self):
        if self.how_many_to_end_of_execution() > TestDurationManager._max_recovery_time:
            return True
        return False
